const x = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const field = (key, type, value) => `<field key="${key}" type="${type}">\n<content>${x(value)}</content>\n...\n</field>\n`;
const entries = (o) => `<bwinnamevalue>${Object.entries(o).map(([k, v]) => `<entry key="${k}">${x(v)}</entry>`).join("")}</bwinnamevalue>`;
const item = (name, tpl, id, path, fields, kids = "") =>
  `<item name="${name}" key="${name.toLowerCase()}" template="${tpl}" id="${id}" version="1" language="en" path="${path}">\n<fields>\n${fields.join("")}...\n</fields>\n${kids}...\n</item>\n`;

